# frozen_string_literal: true
# The `Rack::Utils` port (`unescape_path`, `parse_query`, `build_query`), against rack's own answers.
#
# A FRAMEWORK test (`tests/runtime_ruby_unit.rs` runs every file under
# `runtime/ruby/test/` on each `cargo test`), not one that ships into an
# emitted tree: the CRuby/JRuby trees replace `runtime/rack_utils.rb` with
# the rack gem's own `require "rack/utils"` (`project::ruby_runtime_files`).
# Here it is unambiguously the port.
#
# The expectations are rack 3.2.8's, generated by running the gem over
# this list:
#
#     ruby -rrack/utils -e 'CASES.each { |s| r = Rack::Utils.unescape_path(s)
#       puts [s, r.bytes, r.valid_encoding?].inspect }'
#
# The list covers each way a `%` can be read: two hex digits of either
# case, one digit, no digit, a non-hex digit, a `%` at the end, and bytes
# that are and are not valid UTF-8. A `+` is not a space in a path.

require_relative "test_helper"
require_relative "../rack_utils"

class RackUtilsTest < Minitest::Test
  # [path, bytes of the unescaped path, valid UTF-8?]
  CASES = [
    ["/api/a%2Fb", [47, 97, 112, 105, 47, 97, 47, 98], true],
    ["/api/%2e%2E/x", [47, 97, 112, 105, 47, 46, 46, 47, 120], true],
    ["/api/%4", [47, 97, 112, 105, 47, 37, 52], true],
    ["/api/%zz", [47, 97, 112, 105, 47, 37, 122, 122], true],
    ["/api/a+b", [47, 97, 112, 105, 47, 97, 43, 98], true],
    ["/api/%E3%81%82", [47, 97, 112, 105, 47, 227, 129, 130], true],
    ["/api/%ff", [47, 97, 112, 105, 47, 255], false],
    ["%41%", [65, 37], true],
    ["", [], true],
  ].freeze

  def test_every_path_unescapes_as_rack_does
    CASES.each do |path, bytes, valid|
      unescaped = Rack::Utils.unescape_path(path)
      assert_equal bytes, unescaped.bytes, path
      assert_equal valid, unescaped.valid_encoding?, path
      assert_equal Encoding::UTF_8, unescaped.encoding, path
    end
  end
  # rack 3.2.7's `parse_query` and `build_query` over these (Doorkeeper's redirect URI builder calls both).
  QUERIES = [
    ["a=1&b=2", { "a" => "1", "b" => "2" }],
    ["a=1&a=2&a=3", { "a" => ["1", "2", "3"] }],
    ["a&b=", { "a" => nil, "b" => "" }],
    ["=x&&c=%41+b", { "" => "x", "c" => "A b" }],
    ["a=1& b=2", { "a" => "1", "b" => "2" }],
    ["", {}],
    [nil, {}],
    ["k=%E3%81%82", { "k" => "\u3042" }],
    ["a&a=1", { "a" => "1" }],
    ["a=1&a&a=2", { "a" => ["1", nil, "2"] }],
    ["a&a", { "a" => nil }],
  ].freeze

  def test_every_query_parses_as_rack_does
    QUERIES.each { |query, params| assert_equal params, Rack::Utils.parse_query(query), query.inspect }
  end

  def test_a_percent_without_two_hex_digits_is_an_argument_error
    error = assert_raises(ArgumentError) { Rack::Utils.parse_query("a=%4") }
    assert_equal "invalid %-encoding (%4)", error.message
  end

  def test_params_build_the_query_rack_does
    assert_equal "a=1&b&c+d=x+y", Rack::Utils.build_query({ "a" => "1", b: nil, "c d" => "x y" })
    assert_equal "a=1&a&a=2&", Rack::Utils.build_query({ "a" => ["1", nil, "2"], "e" => [] })
    assert_equal "q=a%26b%3Dc%2F%C3%A9", Rack::Utils.build_query({ "q" => "a&b=c/\u00e9" })
  end
end
